def _strict_abi_decode(types: list[str], raw: bytes) -> tuple[Any, ...]:
    values = abi_decode(types, raw)
    if abi_encode(types, values) != raw:
        raise ValueError("Non-canonical ABI output")
    return values


class IDiesisPositionPositionInfo(TypedDict):
    debt_amount: int
